def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            r0 = min(rr for rr, cc in cells)
            r1 = max(rr for rr, cc in cells)
            c0 = min(cc for rr, cc in cells)
            c1 = max(cc for rr, cc in cells)
            height, width = r1 - r0 + 1, c1 - c0 + 1
            if height < 3 or width < 3:
                continue

            # A hollow rectangular outline has every cell on its perimeter.
            if (all(grid[r0][cc] == color and grid[r1][cc] == color
                    for cc in range(c0, c1 + 1)) and
                all(grid[rr][c0] == color and grid[rr][c1] == color
                    for rr in range(r0, r1 + 1))):
                fill = 7 if height % 2 == 1 and width % 2 == 1 else 2
                for rr in range(r0 + 1, r1):
                    for cc in range(c0 + 1, c1):
                        out[rr][cc] = fill

    return out
